const pi=Math.PI, a=6378137, b=6356752.3, R=(2*a+b)/3, c=299792.458;
const f=1/298.257223563, e2=2*f-f*f;
// complete elliptic integral E(m) numerically
function Em(m,N=400000){const h=(pi/2)/N;let s=0;for(let i=0;i<=N;i++){const w=(i===0||i===N)?1:((i%2)?4:2);s+=w*Math.sqrt(1-m*Math.sin(h*i)**2);}return h/3*s;}
const Ee=Em(e2);
console.log('Rmean',R/1000,'e2',e2.toFixed(8),'E(e)',Ee.toFixed(6));
console.log('Ce km',2*pi*a/1000); console.log('quarter meridian km',a*Ee/1000,'Cm km',4*a*Ee/1000);
console.log('series E:',(pi/2*(1-e2/4-3*e2**2/64)).toFixed(6));
console.log('km/deg mean',4*a*Ee/1000/360,'M28',a*(1-e2)/(1-(1-e2)*Math.sin(28*pi/180)**2)**1.5/1000);
// Eratosthenes
for(const [k,s] of [['Egyptian',157.5],['Attic',184.98]]){const C=250000*s/1000;console.log(k,C.toFixed(0),'km err%',(100*(C-40075)/40075).toFixed(2),'rel meridional',(100*(C-40007.9)/40007.9).toFixed(2));}
// dip & horizon
for(const h of [2,10,11000,20000,400000]){console.log('h='+h,dip:',Math.sqrt(2*R*h).toFixed(0),'m',(Math.acos(R/(R+h))*206265/60).toFixed(4)+"'");}
// Foucault Paris
const phi=48.8566*pi/180; console.log('sin',Math.sin(phi).toFixed(5),'T sid',23.9345/Math.sin(phi),'h; T solar',24/Math.sin(phi),'h');
// parallax & RTT
const D=384399; console.log('parallax',(Math.asin(a/D)*206265).toFixed(3)+"'");
console.log('RTT: per',2*356500/c,'ap',2*406700/c,'mean',2*D/c);
// umbra
const Rs=695700,Dsm=149984400,w_ude=(Rs-R)/Dsm,L=R/w_ude;
for(const dd of [356400,384400,406700]){const r=w_ude*(L-dd);console.log('umbra r@',dd,r.toFixed(1),'km |',(r/1737.4).toFixed(4),'R_M | dia',(2*r/3474.8).toFixed(3),'MoonD');}
// great circles haversine
function hav(lat1,l1,lat2,l2){const p=lat1*pi/180,q=lat2*pi/180,dp=(lat2-lat1)*pi/180,dl=(l2-l1)*pi/180;const A=Math.sin(dp/2)**2+Math.cos(p)*Math.cos(q)*Math.sin(dl/2)**2;return [A,2*Math.atan2(Math.sqrt(A),Math.sqrt(1-A))];}
for(const [nm,pt] of [['SYD-SCL',[-33.9467,151.1819,-33.3926,-70.7858]],['PER-LHR',[-31.9403,115.9667,51.4706,-0.4543]],['AKL-DOH',[-37.0081,174.7850,25.2732,51.6089]],['LHR-SYD',[51.5074,-0.1278,-33.8688,151.2093]]]){const [A,d]=hav(...pt);console.log(nm,R*d/1000,'km');}
// STAR ANALYSIS (corrected)
const Esun=1.37e5, albLow=0.07, albHi=0.16;
const fmm=60, Nf=11, Dap=fmm/Nf/1000; // m
const airyDiam=1.22*0.555e-6*Dap*fmm; // rad* f = linear diam on film (m)
console.log('Airy core diam on film um',(airyDiam*1e6).toFixed(2),'-> arcsec diam',(airyDiam/fmm*206265).toFixed(2));
const A_lens=pi*(Dap/2)**2;
const Estar=Esun*Math.pow(10,(6+26.74)/-2.5); // mag-6 star illuminance at lens
const Apsf=pi*(airyDiam/2)**2;
const Estar_film=Estar*A_lens/Apsf;
for(const alb of [albLow,albHi]){const Ls=alb*Esun/pi;const Esurf_film=pi*Ls/(4*Nf*Nf);console.log('alb',alb,'L',Ls.toFixed(0),'cd/m2 | Efilm surf',Esurf_film.toFixed(2),'lx | star film',Estar_film.toFixed(4),'lx | ratio',(Esurf_film/Estar_film).toFixed(0),'= mag',(2.5*Math.log10(Esurf_film/Estar_film)).toFixed(2),'= stops',(Math.log2(Esurf_film/Estar_film)).toFixed(1));}
// exposure at ASA160: mid-gray H ~ 1/160 lx*s
const H160=1/160;
for(const alb of [albLow,albHi]){const Ls=alb*Esun/pi;const Esurf_film=pi*Ls/(4*Nf*Nf);const ts=H160/Esurf_film;const tstar=H160/Estar_film;console.log('alb',alb,'t_surf',ts.toExponential(2)+'s (= 1/'+Math.round(1/ts)+')','t_star',tstar.toFixed(1)+'s','factor',(tstar/ts).toExponential(2));}
// threshold magnitude for star at film floor: m such that star_psf = threshold density
const mSurf=-12.74+2.5*Math.log10(pi*465**2); // surface brightness mag/arcsec2 (full moon)
console.log('moon surface brightness',mSurf.toFixed(3),'mag/arcsec2');
const Apsf_arc=pi*airyDiam/fmm*0.5*206265; // area arcsec^2 approx using diam
const Apsf_arc2=pi*((airyDiam/fmm)*206265/2)**2;
console.log('PSF area arcsec2',Apsf_arc2.toFixed(0));
for(const m of [-1.46,0,2,6]){const sb=m+2.5*Math.log10(Apsf_arc2);console.log('star mag',m,'spot surface brightness',sb.toFixed(2),'mag/arcsec2 -> gap',(sb-mSurf).toFixed(2),'mag =',(Apsf_arc2===0?'':(sb-mSurf)/2.5),'stops');}
