for(const h of [2,10,11000,20000,400000]) console.log('6  h='+h+'m  d='+Math.sqrt(2*R*h).toFixed(0)+' m  dip='+(Math.acos(R/(R+h))*206265/60).toFixed(4)+"' = "+(Math.acos(R/(R+h))*180/pi).toFixed(4)+' deg');
