console.log('10 umbra: L='+(Lu/1000).toFixed(0)+'km; r(384399)='+(wu*(Lu-D)).toFixed(0)+' km = '+(wu*(Lu-D)/1737.4).toFixed(4)+' R_M; r(perigee..apogee) = '+(wu*(Lu-356400)).toFixed(0)+'..'+(wu*(Lu-406700)).toFixed(0)+' km = '+(wu*(Lu-406700)/1737.4).toFixed(3)+'..'+(wu*(Lu-356400)/1737.4).toFixed(3)+' R_M');
function gc(la1,lo1,la2,lo2){const p=la1*pi/180,q=la2*pi/180,dp=(la2-la1)*pi/180,dl=(lo2-lo1)*pi/180;const A=Math.sin(dp/2)**2+Math.cos(p)*Math.cos(q)*Math.sin(dl/2)**2;return 2*Math.atan2(Math.sqrt(A),Math.sqrt(1-A));}
for(const [n,r] of [['SYD-SCL',[-33.9467,151.1819,-33.3926,-70.7858]],['PER-LHR',[-31.9403,115.9667,51.4706,-0.4543]],['AKL-DOH',[-37.0081,174.7850,25.2732,51.6089]],['LHR-SYD',[51.5074,-0.1278,-33.8688,151.2093]]]) console.log('14 '+n+' = '+(R*gc(...r)/1000).toFixed(1)+' km');
console.log('15 Apollo sum = ',(21.55+34.35+42.28+76.74+95.71+110.52).toFixed(2),'kg | 16 Luna sum =',101+55+170,'g');
console.log('13 spherical excess A=1e12: ',(1e12/(R*R)).toFixed(4),'rad =',(1e12/(R*R)*180/pi).toFixed(2),'deg');
