  for(const ab of [0.07]){const L=ab*Esun/pi;const Es=pi*L/(4*Nf*Nf);
    console.log('  PSF '+areaU+' um2: E_film surf='+Es.toFixed(2)+' lx, star spot='+Ef.toExponential(3)+' lx, ratio='+(Es/Ef).toExponential(2)+' ('+Math.log2(Es/Ef).toFixed(1)+' stops)');
    const gap=m=>Math.log2(Es/Ef)-(6-m)/2.5*Math.log2(10);
    for(const m of [-1.46,0,2,6]) console.log('      mag'+m+' -> '+gap(m).toFixed(1)+' stops under surface mid-density');
  }
}
const L=0.07*Esun/pi, Es=pi*L/(4*Nf*Nf);
console.log('  ASA160 t_surf='+(1/160/Es).toExponential(2)+'s (= 1/'+Math.round(1/(1/160/Es))+') t_mag6star(PSF 174)='+(1/160/(Estar*Alens/(174e-12))).toFixed(2)+'s');
console.log('  moon surface brightness = '+(-12.74+2.5*Math.log10(pi*930*930)).toFixed(2)+' mag/arcsec2 (check)');
