const qs=[
'memory distortion in people reporting abduction by aliens Clancy McNally 2002',
'psychophysiological responding during script-driven imagery alien encounters McNally Lasko 2004',
'lifetime prevalence rates of sleep paralysis across the lifespan Sharpless Barber 2011',
'prevalence of hallucinations and pathological phenomena in the general population sleep paralysis Ohayon 1999 Sleep',
'lunar laser ranging Apache Point Observatory normal points Murphy 2013',
'Lunar heat flow rocks Apollo 17 Taurus-Littrow Langseth New Heat Flow',
'a circumsolar ring of UV photographs Apollo 16',
'UV photography of the lunar sky Apollo 16 far ultraviolet camera Lyman alpha',
'Reassessment of Soviet-US lunar sample exchange Luna 16 20 24',
'Pflock Roswell inconvenient facts and the will to believe',
'Smith and associates lunar laser ranging observatory infrared',
'Apollo 11 close-up photography? no',
'MEASURED LUNAR ROTATIVATION spherical harmonic',
'10^4 no'];
(async()=>{
for(const q of qs){
  try{
    const r=await fetch('https://api.crossref.org/works?rows=3&query.bibliographic='+encodeURIComponent(q),{headers:{'User-Agent':'Kepler/1.0 (research verification; mailto:agent@example.org)'}});
    const j=await r.json();
    console.log('Q: '+q);
    const items=(j.message&&j.message.items)||[];
    if(!items.length) console.log('   (no crossref results)');
    items.forEach(it=>{
      const parts=[it.title&&it.title[0],it['container-title']&&it['container-title'][0],it.volume,it.issue,it.page,(it.issued&&it.issued['date-parts']&&it.issued['date-parts'][0]||[])[0],it.type,it.DOI];
      console.log('   * '+(parts.filter(Boolean).join(' | ')));
    });
  }catch(e){console.log('Q: '+q+'\n   ERROR '+e.message);}
  console.log();
}
})();
