import json, re, urllib.request, urllib.parse

def get(url, data=None, ctype=None):
    h = {'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Safari/537.36',
         'Accept': 'text/html,application/json,*/*'}
    if ctype:
        h['Content-Type'] = ctype
    req = urllib.request.Request(url, headers=h, data=data)
    with urllib.request.urlopen(req, timeout=60) as r:
        return r.read()

# 1. Wikipedia: lunar surface / heat flow experiment
for title in ["Heat Flow Experiment", "Apollo Lunar Surface Experiments Package"]:
    try:
        u = ("https://en.wikipedia.org/w/api.php?action=query&prop=extracts&explaintext=1&redirects=1&titles=%s&format=json"
             % urllib.parse.quote(title))
        d = json.loads(get(u))
        txt = list(d['query']['pages'].values())[0].get('extract', '')
        print("### Wikipedia: %s (%d chars)" % (title, len(txt)))
        for m in re.finditer(r'[^.]{0,220}(mW|heat flow|thermal conductivity)[^.]{0,220}\.', txt, flags=re.I):
            print("   -", m.group(0).strip()[:400])
        print()
    except Exception as e:
        print(title, "ERR", repr(e))

# 2. NTRS search API
for q in ["Biomedical Results of Apollo", "Apollo 11 preliminary science report"]:
    try:
        body = json.dumps({"query": [{"type": "basic", "op": "and", "field": "title", "value": q}], "page": {"size": 5, "from": 0}}).encode()
        d = json.loads(get("https://ntrs.nasa.gov/api/citations/search", data=body, ctype="application/json"))
        print("### NTRS search: %s" % q)
        for r in d.get('results', [])[:5]:
            print("   %s | %s | %s" % (r.get('id'), r.get('title', '')[:90], r.get('distribution', '')))
        print()
    except Exception as e:
        print(q, "ERR", repr(e))

